@namespace sv_33df41e661294aafb9c9cfcbb2dfa73d.Components.Pages.Settings
@using sv_33df41e661294aafb9c9cfcbb2dfa73d.Services
@inject ISettingsService SettingsService

<div class="settings-section appearance-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="form-group">
            <h3>Theme</h3>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange="() => _theme = &quot;Light&quot;" />
                    <span>Light</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange="() => _theme = &quot;Dark&quot;" />
                    <span>Dark</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange="() => _theme = &quot;System&quot;" />
                    <span>System</span>
                </label>
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange="() => _fontSize = &quot;Small&quot;" />
                    <span>Small</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange="() => _fontSize = &quot;Medium&quot;" />
                    <span>Medium</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange="() => _fontSize = &quot;Large&quot;" />
                    <span>Large</span>
                </label>
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <h3>Language</h3>
            <select @bind="_language" class="form-control">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
                <option value="zh">Chinese</option>
            </select>
        </div>

        <!-- Compact Mode Toggle -->
        <div class="form-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" class="toggle-switch" />
                <span>Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="appearance-preview @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <div class="preview-content">
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <button class="preview-button">Sample Button</button>
                <div class="preview-card">
                    <strong>Card Title</strong>
                    <p>Some example content to demonstrate spacing and typography.</p>
                </div>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast toast-success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

