+    min-height: calc(100vh - 4rem);
+    gap: 0;
+}
+
+/* Sidebar */
+.settings-sidebar {
+    width: 240px;
+    background: var(--bs-body-bg, #f8f9fa);
+    border-right: 1px solid var(--bs-border-color, #dee2e6);
+    padding: 1.5rem 0;
+    flex-shrink: 0;
+}
+
+.settings-nav {
+    list-style: none;
+    padding: 0;
+    margin: 0;
+}
+
+.settings-nav-item {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    padding: 0.75rem 1.5rem;
+    cursor: pointer;
+    transition: background-color 0.15s, border-left 0.15s;
+    border-left: 3px solid transparent;
+    font-weight: 500;
+}
+
+.settings-nav-item:hover {
+    background-color: rgba(0, 0, 0, 0.04);
+}
+
+.settings-nav-item.active {
+    background-color: rgba(13, 110, 253, 0.08);
+    border-left-color: #0d6efd;
+    color: #0d6efd;
+}
+
+.settings-nav-icon {
+    font-size: 1.2rem;
+}
+
+/* Main Content */
+.settings-content {
+    flex: 1;
+    padding: 2rem;
+    max-width: 800px;
+}
+
+.settings-section h2 {
+    margin-bottom: 1.5rem;
+    font-size: 1.5rem;
+    font-weight: 600;
+}
+
+.settings-section h3 {
+    margin-top: 1.5rem;
+    margin-bottom: 0.75rem;
+    font-size: 1.1rem;
+    font-weight: 600;
+}
+
+/* Form Controls */
+.form-group {
+    margin-bottom: 1rem;
+}
+
+.form-group label {
+    display: block;
+    margin-bottom: 0.375rem;
+    font-weight: 500;
+    font-size: 0.9rem;
+}
+
+.form-control {
+    width: 100%;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #dee2e6;
+    border-radius: 0.375rem;
+    font-size: 0.95rem;
+    transition: border-color 0.15s;
+}
+
+.form-control:focus {
+    outline: none;
+    border-color: #0d6efd;
+    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.15);
+}
+
+textarea.form-control {
+    resize: vertical;
+}
+
+/* Buttons */
+.btn {
+    display: inline-flex;
+    align-items: center;
+    padding: 0.5rem 1rem;
+    border: none;
+    border-radius: 0.375rem;
+    font-size: 0.9rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background-color 0.15s;
+}
+
+.btn-primary {
+    background-color: #0d6efd;
+    color: white;
+}
+
+.btn-primary:hover {
+    background-color: #0b5ed7;
+}
+
+.btn-secondary {
+    background-color: #6c757d;
+    color: white;
+}
+
+.btn-secondary:hover {
+    background-color: #5c636a;
+}
+
+.btn-danger {
+    background-color: #dc3545;
+    color: white;
+}
+
+.btn-danger:hover {
+    background-color: #bb2d3b;
+}
+
+.btn-sm {
+    padding: 0.25rem 0.5rem;
+    font-size: 0.8rem;
+}
+
+.form-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+}
+
+/* Toast */
+.toast {
+    margin-top: 1rem;
+    padding: 0.75rem 1rem;
+    border-radius: 0.375rem;
+    font-size: 0.9rem;
+    animation: fadeIn 0.3s ease;
+}
+
+.toast-success {
+    background-color: #d1e7dd;
+    color: #0f5132;
+    border: 1px solid #badbcc;
+}
+
+@@keyframes fadeIn {
+    from { opacity: 0; transform: translateY(-0.5rem); }
+    to { opacity: 1; transform: translateY(0); }
+}
+
+/* Avatar */
+.avatar-preview {
+    margin-bottom: 1.5rem;
+    text-align: center;
+}
+
+.avatar-image {
+    width: 96px;
+    height: 96px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 3px solid #dee2e6;
+}
+
+.avatar-url-label {
+    margin-top: 0.5rem;
+    font-size: 0.8rem;
+    color: #6c757d;
+    word-break: break-all;
+}
+
+/* Toggle Items */
+.toggle-group {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+}
+
+.toggle-item {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    cursor: pointer;
+    font-size: 0.95rem;
+}
+
+.toggle-switch {
+    width: 1.2rem;
+    height: 1.2rem;
+    accent-color: #0d6efd;
+}
+
+/* Channels */
+.channels-section {
+    margin-top: 1.5rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.375rem 0;
+    cursor: pointer;
+    font-size: 0.9rem;
+}
+
+/* Expandable Panel */
+.expandable-panel {
+    border: 1px solid #dee2e6;
+    border-radius: 0.375rem;
+    margin-bottom: 1.5rem;
+}
+
+.panel-header {
+    width: 100%;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    background: #f8f9fa;
+    border: none;
+    border-radius: 0.375rem;
+    cursor: pointer;
+    font-weight: 500;
+    font-size: 0.95rem;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.panel-content {
+    padding: 1rem;
+    border-top: 1px solid #dee2e6;
+}
+
+/* Two-Factor */
+.twofa-section {
+    margin-bottom: 1.5rem;
+}
+
+.twofa-status {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+    flex-wrap: wrap;
+}
+
+.status-indicator {
+    font-weight: 500;
+    font-size: 0.9rem;
+}
+
+.status-enabled {
+    color: #198754;
+}
+
+.status-disabled {
+    color: #dc3545;
+}
+
+.last-change {
+    margin-top: 0.5rem;
+    font-size: 0.85rem;
+    color: #6c757d;
+}
+
+/* Sessions Table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.625rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+}
+
+.current-session-badge {
+    display: inline-block;
+    padding: 0.2rem 0.5rem;
+    background: #e2e3e5;
+    border-radius: 0.25rem;
+    font-size: 0.75rem;
+    color: #41464b;
+}
+
+/* Dialog */
+.dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: white;
+    border-radius: 0.5rem;
+    padding: 1.5rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
+}
+
+.dialog h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+    justify-content: flex-end;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    flex-wrap: wrap;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.375rem;
+    cursor: pointer;
+    font-size: 0.95rem;
+}
+
+/* Appearance Preview */
+.appearance-preview {
+    margin-top: 1.5rem;
+    padding: 1.25rem;
+    border: 1px solid #dee2e6;
+    border-radius: 0.5rem;
+    transition: all 0.3s ease;
+}
+
+.appearance-preview h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+    font-size: 1rem;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-theme-dark {
+    background: #1a1a2e;
+    color: #e0e0e0;
+    border-color: #333;
+}
+
+.preview-theme-system {
+    background: #f0f0f0;
+    color: #333;
+}
+
+.preview-font-small .preview-text {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium .preview-text {
+    font-size: 1rem;
+}
+
+.preview-font-large .preview-text {
+    font-size: 1.2rem;
+}
+
+.preview-compact .preview-content {
+    line-height: 1.2;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+}
+
+.preview-button {
+    display: inline-block;
+    margin: 0.5rem 0;
+    padding: 0.375rem 0.75rem;
+    border: none;
+    border-radius: 0.25rem;
+    background: #0d6efd;
+    color: white;
+    font-size: inherit;
+    cursor: default;
+}
+
+.preview-theme-dark .preview-button {
+    background: #6ea8fe;
+    color: #000;
+}
+
+.preview-card {
+    margin-top: 0.75rem;
+    padding: 0.75rem;
+    border: 1px solid currentColor;
+    border-radius: 0.375rem;
+    opacity: 0.8;
+}
+
+.preview-card p {
+    margin: 0.375rem 0 0;
+    font-size: 0.85em;
+}
+
+/* Error */
+.error-message {
+    color: #dc3545;
+    font-size: 0.85rem;
+    margin-bottom: 0.75rem;
+}
+
+.loading {
+    color: #6c757d;
+    font-style: italic;
+}
+

